"use client";

import * as React from "react";
import { Download, FileSpreadsheet } from "lucide-react";
import { CsvMapper } from "./csv-mapper";
import { autoMatch, parseCsv, toCsv } from "./csv-parse";
import { NumberRoll } from "./number-roll";
import { StatusButton } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CSV IMPORT: Contacts → Import, done properly
 *
 *   drop      drop a file (the target lifts to meet it) or
 *             choose one; it's read in slices with the row
 *             count rolling, so a big file never freezes the page
 *   match     the file's columns line up against your fields;
 *             the ones that match by name are threaded together
 *             already. Carry a column onto a field to change it,
 *             or use the field's select
 *   review    "2,996 ready · 4 need a look": the rows with
 *             problems open with their bad cells as fields;
 *             fix one and it ticks and folds away, the counts
 *             rolling. Or skip what's left
 *   import    rows go to onImport in batches; the bar fills and
 *             "1,250 of 2,996" rolls; Cancel stops after the
 *             batch in flight
 *   done      a ring and a check draw; anything skipped or
 *             refused downloads as a CSV with the reason per row
 *
 * The file never leaves the browser until onImport sends your
 * rows, already shaped as { [field]: value }.
 * ───────────────────────────────────────────────────────── */

export interface CsvField {
  key: string;
  label: string;
  required?: boolean;
  /** Other names the column might have in a file, e.g. ["e-mail", "email address"]. */
  match?: string[];
  /** Return why a value won't do. */
  validate?: (
    value: string,
    row: Record<string, string>,
  ) => string | null | undefined | void;
}

export interface CsvImportResult {
  /** Rows in this batch your server refused, by their index in the batch. */
  failed?: { index: number; reason: string }[];
}

export interface CsvImportHandle {
  /** Reads text as if it were a dropped file. */
  load: (text: string, name?: string) => void;
}

export interface CsvImportProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  fields: CsvField[];
  /** Saves one batch of rows. Throw to mark the whole batch as not imported. */
  onImport: (
    rows: Record<string, string>[],
    options: { signal: AbortSignal; start: number },
  ) => Promise<CsvImportResult | void>;
  /** Rows per onImport call. */
  batchSize?: number;
  maxRows?: number;
  /** What a row is: { one: "contact", many: "contacts" }. */
  noun?: { one: string; many: string };
  /** A link to a template file to fill in. */
  templateHref?: string;
  title?: string;
  description?: string;
  onDone?: (summary: {
    imported: number;
    skipped: number;
    cancelled: boolean;
  }) => void;
  ref?: React.Ref<CsvImportHandle>;
}

type Step = "drop" | "map" | "review" | "import" | "done";
type Skipped = { row: Record<string, string>; reason: string };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ORDER: Step[] = ["drop", "map", "review", "import", "done"];
const SHOWN = 40;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const count = (n: number) => n.toLocaleString("en-GB");

function Face({
  out,
  enter,
  dir,
  reduced,
  onGone,
  children,
}: {
  out: boolean;
  enter: boolean;
  dir: number;
  reduced: boolean;
  onGone: () => void;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.getAnimations().forEach((a) => a.cancel());
    if (reduced) return;
    if (out) {
      const a = el.animate(
        [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          {
            opacity: 0,
            transform: `translateX(${-dir * 28}px)`,
            filter: "blur(4px)",
          },
        ],
        { duration: 240, easing: EASE, fill: "forwards" },
      );
      a.onfinish = onGone;
      return;
    }
    if (enter)
      el.animate(
        [
          {
            opacity: 0,
            transform: `translateX(${dir * 28}px)`,
            filter: "blur(4px)",
          },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 440, delay: 80, easing: EASE, fill: "backwards" },
      );
  }, [out]);
  return (
    <div
      ref={ref}
      inert={out}
      aria-hidden={out || undefined}
      className={out ? "pointer-events-none absolute inset-x-0 top-0" : ""}
    >
      {children}
    </div>
  );
}

/** Steps slide in from the side you went; the card eases to the new height. */
function Slides({
  step,
  dir,
  reduced,
  render,
}: {
  step: Step;
  dir: number;
  reduced: boolean;
  render: (s: Step) => React.ReactNode;
}) {
  const [faces, setFaces] = React.useState<
    { s: Step; out: boolean; dir: number; enter: boolean }[]
  >([{ s: step, out: false, dir, enter: false }]);
  const [seen, setSeen] = React.useState(step);
  const boxRef = React.useRef<HTMLDivElement>(null);
  const height = React.useRef(0);
  // Clipped only while a step slides; at rest a menu can open past its edge.
  const [moving, setMoving] = React.useState(false);
  React.useEffect(() => {
    if (!moving) return;
    const timer = window.setTimeout(() => setMoving(false), 560);
    return () => window.clearTimeout(timer);
  }, [moving, step]);
  if (seen !== step) {
    setSeen(step);
    if (!reduced) setMoving(true);
    setFaces((f) => [
      ...f.filter((x) => x.out && x.s !== step && x.s !== seen),
      ...(reduced ? [] : [{ s: seen, out: true, dir, enter: false }]),
      { s: step, out: false, dir, enter: true },
    ]);
  }
  React.useLayoutEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    height.current = el.offsetHeight;
    const observer = new ResizeObserver(
      () => (height.current = el.offsetHeight),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  React.useLayoutEffect(() => {
    const el = boxRef.current;
    if (!el || reduced) return;
    const to = el.offsetHeight;
    if (Math.abs(to - height.current) > 0.5)
      el.animate([{ height: `${height.current}px` }, { height: `${to}px` }], {
        duration: 460,
        easing: EASE,
      });
  }, [step]);
  return (
    <div
      ref={boxRef}
      className="relative [overflow-clip-margin:8px]"
      style={{ overflowY: moving ? "clip" : "visible" }}
    >
      {faces.map((f) => (
        <Face
          key={f.s}
          out={f.out}
          enter={f.enter}
          dir={f.dir}
          reduced={reduced}
          onGone={() =>
            setFaces((all) => all.filter((x) => !(x.s === f.s && x.out)))
          }
        >
          {render(f.s)}
        </Face>
      ))}
    </div>
  );
}

function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) {
    setKept(children);
  }
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 420ms ${EASE}, opacity ${open ? 300 : 160}ms ${EASE}`,
      }}
    >
      <div className="min-h-0 min-w-0 overflow-clip [overflow-clip-margin:6px]">
        {open ? children : kept}
      </div>
    </div>
  );
}

function Drawn({
  reduced,
  className = "size-12",
  tone = "text-emerald-600 dark:text-emerald-400",
}: {
  reduced: boolean;
  className?: string;
  tone?: string;
}) {
  const ring = React.useRef<SVGCircleElement>(null);
  const tick = React.useRef<SVGPathElement>(null);
  React.useLayoutEffect(() => {
    if (reduced) return;
    ring.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
      duration: 640,
      delay: 120,
      easing: EASE,
      fill: "backwards",
    });
    tick.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
      duration: 420,
      delay: 560,
      easing: EASE,
      fill: "backwards",
    });
  }, [reduced]);
  return (
    <svg
      viewBox="0 0 48 48"
      fill="none"
      aria-hidden="true"
      className={`${className} ${tone}`}
    >
      <circle cx="24" cy="24" r="22.5" stroke="var(--border)" strokeWidth="1" />
      <circle
        ref={ring}
        cx="24"
        cy="24"
        r="22.5"
        stroke="currentColor"
        strokeWidth="1.25"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={0}
        transform="rotate(-90 24 24)"
      />
      <path
        ref={tick}
        d="M16.5 24.5 21.5 29.5 31.5 18.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={0}
      />
    </svg>
  );
}

function Switch({
  on,
  onToggle,
  label,
  reduced,
}: {
  on: boolean;
  onToggle: () => void;
  label: string;
  reduced: boolean;
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      onClick={onToggle}
      className={`inline-flex cursor-pointer items-center gap-2.5 rounded-full py-1 pr-2 pl-1 text-left text-[12.5px] transition-colors hover:bg-accent/60 ${FOCUS}`}
    >
      <span
        className={`relative h-5 w-9 shrink-0 rounded-full transition-[background-color,box-shadow] duration-300 ${on ? "bg-primary" : "bg-muted shadow-[inset_0_0_0_1px_var(--border)]"}`}
      >
        <span
          className="absolute top-0.5 left-0.5 size-4 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
          style={{
            transform: on ? "translateX(16px)" : "none",
            transition: reduced ? "none" : `transform 420ms ${THROW}`,
          }}
        />
      </span>
      {label}
    </button>
  );
}

/** One row with problems: its bad cells as fields; once they're right it ticks and folds away. */
function ProblemRow({
  index,
  row,
  problems,
  fields,
  fixed,
  reduced,
  onEdit,
}: {
  index: number;
  row: Record<string, string>;
  problems: Record<string, string>;
  fields: CsvField[];
  fixed: boolean;
  reduced: boolean;
  onEdit: (index: number, key: string, value: string) => void;
}) {
  const keys = Object.keys(problems);
  const [shownKeys] = React.useState(keys);
  // Fixed: it says so for a moment, then folds away.
  const [gone, setGone] = React.useState(false);
  const [seenFixed, setSeenFixed] = React.useState(fixed);
  if (fixed !== seenFixed) {
    setSeenFixed(fixed);
    if (!fixed) setGone(false);
  }
  React.useEffect(() => {
    if (!fixed) return;
    const timer = window.setTimeout(() => setGone(true), 650);
    return () => window.clearTimeout(timer);
  }, [fixed]);
  const context = fields
    .filter((f) => !shownKeys.includes(f.key) && row[f.key])
    .slice(0, 2);
  return (
    <Fold open={!gone} reduced={reduced}>
      <div className="mb-2 rounded-[12px] px-3 py-2.5 shadow-[inset_0_0_0_1px_var(--border)]">
        <p className="flex items-center gap-2 text-[11.5px] text-muted-foreground">
          <span className="font-mono">Row {count(index + 2)}</span>
          {context.length > 0 && (
            <span className="min-w-0 truncate">
              · {context.map((f) => row[f.key]).join(" · ")}
            </span>
          )}
          <span
            className={`ml-auto inline-flex shrink-0 items-center gap-1 transition-colors ${fixed ? "text-emerald-600 dark:text-emerald-400" : "text-amber-700 dark:text-amber-400"}`}
          >
            <TextMorph>
              {fixed
                ? "Fixed"
                : keys.length === 1
                  ? "1 problem"
                  : `${keys.length} problems`}
            </TextMorph>
          </span>
        </p>
        <div className="mt-2 grid gap-2 @md:grid-cols-2">
          {shownKeys.map((k) => {
            const f = fields.find((x) => x.key === k)!;
            const bad = problems[k];
            return (
              <label key={k} className="block min-w-0">
                <span className="block text-[11.5px] font-medium">
                  {f.label}
                </span>
                <input
                  value={row[k] ?? ""}
                  onChange={(e) => onEdit(index, k, e.target.value)}
                  aria-invalid={Boolean(bad) || undefined}
                  className={`mt-1 h-8 w-full rounded-[8px] bg-transparent px-2.5 text-[16px] text-foreground outline-none transition-shadow [@media(pointer:fine)]:text-[12.5px] ${
                    bad
                      ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]"
                      : "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-emerald-500)_45%,transparent)]"
                  }`}
                />
                <span
                  className={`mt-1 block text-[11px] transition-colors ${bad ? "text-red-600 dark:text-red-400" : "text-emerald-600 dark:text-emerald-400"}`}
                >
                  {bad ?? "Looks right"}
                </span>
              </label>
            );
          })}
        </div>
      </div>
    </Fold>
  );
}

export function CsvImport({
  fields,
  onImport,
  batchSize = 250,
  maxRows = 50_000,
  noun = { one: "row", many: "rows" },
  templateHref,
  title = "Import",
  description = "Bring rows in from a spreadsheet. Nothing is saved until you import.",
  onDone,
  ref,
  className = "",
  ...props
}: CsvImportProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [step, setStep] = React.useState<Step>("drop");
  const [dir, setDir] = React.useState(1);
  const [fileName, setFileName] = React.useState("");
  const [headers, setHeaders] = React.useState<string[]>([]);
  const [data, setData] = React.useState<string[][]>([]);
  const [mapping, setMapping] = React.useState<Record<string, number | null>>(
    {},
  );
  const [reading, setReading] = React.useState<{ name: string } | null>(null);
  const [dropError, setDropError] = React.useState<string | null>(null);
  const [over, setOver] = React.useState(false);
  const [edits, setEdits] = React.useState<
    Record<number, Record<string, string>>
  >({});
  const [fixing, setFixing] = React.useState<number[]>([]);
  const [skipBad, setSkipBad] = React.useState(true);
  const [progress, setProgress] = React.useState({ done: 0, total: 0 });
  const [result, setResult] = React.useState<{
    imported: number;
    skipped: Skipped[];
    cancelled: boolean;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const dropRef = React.useRef<HTMLLabelElement>(null);
  const ctrl = React.useRef<AbortController | null>(null);
  const many = noun.many;

  const go = (next: Step) => {
    setDir(ORDER.indexOf(next) >= ORDER.indexOf(step) ? 1 : -1);
    setStep(next);
  };

  const read = async (text: string, name: string) => {
    setDropError(null);
    setReading({ name });
    try {
      const rows = await parseCsv(text);
      const [head, ...body] = rows;
      if (!head || !body.length)
        throw new Error("That file has no rows under its header.");
      if (body.length > maxRows)
        throw new Error(
          `That file has ${count(body.length)} rows; up to ${count(maxRows)} can be imported at once.`,
        );
      const width = head.length;
      setHeaders(head.map((h) => h.trim()));
      setData(
        body.map((r) =>
          r.length === width
            ? r
            : [...r, ...Array(Math.max(0, width - r.length)).fill("")].slice(
                0,
                width,
              ),
        ),
      );
      setMapping(autoMatch(head, fields));
      setEdits({});
      setFixing([]);
      setFileName(name);
      setReading(null);
      go("map");
      setAnnounce(
        `${name}: ${count(body.length)} ${body.length === 1 ? noun.one : many}, ${width} columns. Match them to your fields.`,
      );
    } catch (e) {
      setReading(null);
      setDropError(message(e, "That file couldn't be read."));
      if (!reduced)
        dropRef.current?.animate(
          [
            { transform: "none" },
            { transform: "translateX(-4px)" },
            { transform: "translateX(4px)" },
            { transform: "translateX(-2px)" },
            { transform: "none" },
          ],
          { duration: 380, easing: "ease-out" },
        );
    }
  };

  const take = async (file: File | undefined) => {
    if (!file) return;
    if (!/\.(csv|tsv|txt)$/i.test(file.name) && !/^text\//.test(file.type)) {
      setDropError(
        `“${file.name}” isn't a CSV file. Export your sheet as CSV first.`,
      );
      return;
    }
    read(await file.text(), file.name);
  };

  React.useImperativeHandle(ref, () => ({
    load: (text, name = "pasted.csv") => read(text, name),
  }));

  const rowAt = React.useCallback(
    (i: number) => {
      const out: Record<string, string> = {};
      for (const f of fields) {
        const col = mapping[f.key];
        out[f.key] =
          edits[i]?.[f.key] ??
          (col === null || col === undefined
            ? ""
            : (data[i]?.[col] ?? "").trim());
      }
      return out;
    },
    [fields, mapping, edits, data],
  );

  const problemsOf = React.useCallback(
    (row: Record<string, string>) => {
      const out: Record<string, string> = {};
      for (const f of fields) {
        const v = row[f.key];
        if (f.required && !v) out[f.key] = `${f.label} is missing.`;
        else if (v && f.validate) {
          const why = f.validate(v, row);
          if (why) out[f.key] = why;
        }
      }
      return out;
    },
    [fields],
  );

  // Every row is checked once per mapping; an edit re-checks only its own row.
  const checking = step === "review" || step === "import";
  const base = React.useMemo(() => {
    if (!checking) return [];
    return data.map((r) => {
      const row: Record<string, string> = {};
      for (const f of fields) {
        const col = mapping[f.key];
        row[f.key] =
          col === null || col === undefined ? "" : (r[col] ?? "").trim();
      }
      return problemsOf(row);
    });
  }, [checking, data, mapping, fields, problemsOf]);
  const checks = React.useMemo(() => {
    const next = base.slice();
    for (const i of Object.keys(edits))
      next[Number(i)] = problemsOf(rowAt(Number(i)));
    return next;
  }, [base, edits, problemsOf, rowAt]);
  const bad = React.useMemo(
    () =>
      checks
        .map((p, i) => (Object.keys(p).length ? i : -1))
        .filter((i) => i >= 0),
    [checks],
  );
  const ready = data.length - bad.length;
  const missing = fields.filter(
    (f) =>
      f.required && (mapping[f.key] === null || mapping[f.key] === undefined),
  );
  const matched = fields.filter(
    (f) => mapping[f.key] !== null && mapping[f.key] !== undefined,
  ).length;
  const samples = React.useMemo(
    () => headers.map((_, c) => data.slice(0, 6).map((r) => r[c] ?? "")),
    [headers, data],
  );
  const listed = [...new Set([...bad.slice(0, SHOWN), ...fixing])].sort(
    (a, b) => a - b,
  );

  const edit = (index: number, key: string, value: string) => {
    setEdits((e) => ({ ...e, [index]: { ...e[index], [key]: value } }));
    const row = { ...rowAt(index), [key]: value };
    if (!Object.keys(problemsOf(row)).length && !fixing.includes(index)) {
      // Fixed: it stays to say so, then folds away.
      setFixing((f) => [...f, index]);
      window.setTimeout(
        () => setFixing((f) => f.filter((x) => x !== index)),
        1400,
      );
    }
  };

  const run = async () => {
    const indices = data.map((_, i) => i).filter((i) => !bad.includes(i));
    const rows = indices.map(rowAt);
    const skipped: Skipped[] = bad.map((i) => ({
      row: rowAt(i),
      reason: Object.values(checks[i]).join(" "),
    }));
    const c = new AbortController();
    ctrl.current = c;
    setProgress({ done: 0, total: rows.length });
    go("import");
    let imported = 0;
    for (let s = 0; s < rows.length; s += batchSize) {
      if (c.signal.aborted) break;
      const batch = rows.slice(s, s + batchSize);
      try {
        const r = await onImport(batch, { signal: c.signal, start: s });
        const failed = (r ? r.failed : undefined) ?? [];
        failed.forEach(
          (f) =>
            batch[f.index] &&
            skipped.push({ row: batch[f.index], reason: f.reason }),
        );
        imported += batch.length - failed.length;
      } catch (e) {
        if (c.signal.aborted) break;
        const why = message(e, "Your server didn't take this batch.");
        batch.forEach((row) => skipped.push({ row, reason: why }));
      }
      setProgress({
        done: Math.min(rows.length, s + batch.length),
        total: rows.length,
      });
    }
    const cancelled = c.signal.aborted;
    setResult({ imported, skipped, cancelled });
    go("done");
    setAnnounce(
      `${count(imported)} ${imported === 1 ? noun.one : many} imported${skipped.length ? `, ${count(skipped.length)} skipped` : ""}${cancelled ? ". Stopped early" : ""}.`,
    );
    onDone?.({ imported, skipped: skipped.length, cancelled });
  };

  const reset = () => {
    setResult(null);
    setData([]);
    setHeaders([]);
    setFileName("");
    go("drop");
    requestAnimationFrame(() =>
      inputRef.current?.focus({ preventScroll: true }),
    );
  };

  // The skipped rows, as a file to fix and import again.
  const skippedHref = React.useMemo(() => {
    if (!result?.skipped.length) return null;
    const csv = toCsv([
      [...fields.map((f) => f.label), "Why it was skipped"],
      ...result.skipped.map((s) => [
        ...fields.map((f) => s.row[f.key] ?? ""),
        s.reason,
      ]),
    ]);
    return URL.createObjectURL(
      new Blob([csv], { type: "text/csv;charset=utf-8" }),
    );
  }, [result, fields]);
  React.useEffect(
    () => () => void (skippedHref && URL.revokeObjectURL(skippedHref)),
    [skippedHref],
  );

  const header = (
    <div className="flex items-center gap-2.5">
      <span className="grid size-8 shrink-0 place-items-center rounded-[9px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
        <FileSpreadsheet
          className="size-4"
          strokeWidth={1.75}
          aria-hidden="true"
        />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[13px] font-medium">
          {fileName}
        </span>
        <span className="block text-[11.5px] text-muted-foreground tabular-nums">
          {count(data.length)} {data.length === 1 ? noun.one : many} ·{" "}
          {headers.length} columns
        </span>
      </span>
    </div>
  );

  const render = (s: Step): React.ReactNode => {
    if (s === "drop")
      return (
        <div className="px-4 pb-4 @md:px-5 @md:pb-5">
          <input
            ref={inputRef}
            id={`${id}-file`}
            type="file"
            accept=".csv,.tsv,.txt,text/csv,text/tab-separated-values,text/plain"
            className="peer sr-only"
            onChange={(e) => {
              take(e.target.files?.[0]);
              e.target.value = "";
            }}
          />
          <label
            ref={dropRef}
            htmlFor={`${id}-file`}
            onDragEnter={(e) => {
              e.preventDefault();
              setOver(true);
            }}
            onDragOver={(e) => {
              e.preventDefault();
              e.dataTransfer.dropEffect = "copy";
            }}
            onDragLeave={(e) => {
              if (!e.currentTarget.contains(e.relatedTarget as Node))
                setOver(false);
            }}
            onDrop={(e) => {
              e.preventDefault();
              setOver(false);
              take(e.dataTransfer.files[0]);
            }}
            className={`flex cursor-pointer flex-col items-center justify-center rounded-[16px] border border-dashed px-4 py-9 text-center transition-[background-color,border-color] duration-300 peer-focus-visible:ring-2 peer-focus-visible:ring-ring/40 ${
              over
                ? "border-primary bg-accent"
                : dropError
                  ? "border-red-500/50"
                  : "border-border hover:bg-accent/40"
            }`}
          >
            <span
              className="grid size-11 place-items-center rounded-[12px] bg-background text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
              style={{
                transform: over ? "translateY(-4px) scale(1.06)" : "none",
                transition: reduced ? "none" : `transform 420ms ${THROW}`,
              }}
            >
              {reading ? (
                <span className="size-4 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none" />
              ) : (
                <FileSpreadsheet
                  className="size-5"
                  strokeWidth={1.5}
                  aria-hidden="true"
                />
              )}
            </span>
            <span className="mt-3 text-[13.5px] font-medium">
              <TextMorph>
                {reading
                  ? `Reading ${reading.name}`
                  : over
                    ? "Drop to read it"
                    : "Drop a CSV file here"}
              </TextMorph>
            </span>
            <span className="mt-1 text-[12px] text-muted-foreground">
              or{" "}
              <span className="font-medium text-foreground underline underline-offset-2">
                choose a file
              </span>
            </span>
            <span className="mt-3 text-[11.5px] text-muted-foreground">
              Up to {count(maxRows)} rows. Comma, semicolon or tab separated.
            </span>
          </label>
          <Fold open={Boolean(dropError)} reduced={reduced}>
            <p
              role="alert"
              className="pt-2.5 text-[12px] text-red-600 dark:text-red-400"
            >
              {dropError}
            </p>
          </Fold>
          {templateHref && (
            <a
              href={templateHref}
              download
              className={`mt-3 inline-flex items-center gap-1.5 rounded-sm text-[12px] font-medium text-muted-foreground underline-offset-2 hover:text-foreground hover:underline ${FOCUS}`}
            >
              <Download
                className="size-3.5"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              Download a template
            </a>
          )}
        </div>
      );

    if (s === "map")
      return (
        <div className="px-4 pb-4 @md:px-5 @md:pb-5">
          {header}
          <div className="mt-4 mb-2.5 flex items-baseline justify-between gap-3">
            <p className="text-[12.5px] font-medium">Match your columns</p>
            <p className="text-[11.5px] text-muted-foreground tabular-nums">
              <NumberRoll value={matched} /> of {fields.length} fields matched
            </p>
          </div>
          <CsvMapper
            headers={headers}
            samples={samples}
            fields={fields}
            mapping={mapping}
            onChange={setMapping}
            reduced={reduced}
          />
          <div className="mt-4 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
            <p
              className={`mr-auto min-w-0 text-[11.5px] ${missing.length ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground"}`}
            >
              {missing.length
                ? `Match ${missing.map((f) => f.label).join(" and ")} to continue.`
                : "Carry a column onto a field, or pick it from the list."}
            </p>
            <button
              type="button"
              onClick={reset}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              Change file
            </button>
            <StatusButton
              size="sm"
              labels={{ idle: "Continue" }}
              onClick={() => !missing.length && go("review")}
              aria-disabled={missing.length > 0 || undefined}
              className={missing.length ? "pointer-events-none opacity-50" : ""}
            />
          </div>
        </div>
      );

    if (s === "review") {
      const blocked = !skipBad && bad.length > 0;
      return (
        <div className="px-4 pb-4 @md:px-5 @md:pb-5">
          {header}
          <div className="mt-4 flex flex-wrap gap-2 text-[12px] tabular-nums">
            <span className="inline-flex items-center gap-1.5 rounded-full py-1 pr-2.5 pl-2 text-emerald-700 shadow-[inset_0_0_0_1px_var(--border)] dark:text-emerald-400">
              <span
                className="size-1.5 rounded-full bg-emerald-500"
                aria-hidden="true"
              />
              <NumberRoll value={ready} />
              &nbsp;ready
            </span>
            <span
              className="inline-grid"
              style={{
                gridTemplateColumns: bad.length ? "1fr" : "0fr",
                opacity: bad.length ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 420ms ${EASE}, opacity 260ms ${EASE}`,
              }}
            >
              <span className="min-w-0 overflow-clip">
                <span className="inline-flex items-center gap-1.5 rounded-full py-1 pr-2.5 pl-2 whitespace-nowrap text-amber-800 shadow-[inset_0_0_0_1px_var(--border)] dark:text-amber-400">
                  <span
                    className="size-1.5 rounded-full bg-amber-500"
                    aria-hidden="true"
                  />
                  <NumberRoll value={bad.length || 1} />
                  &nbsp;need a look
                </span>
              </span>
            </span>
          </div>

          <Fold open={listed.length > 0} reduced={reduced}>
            <div className="mt-3 max-h-[19rem] overflow-y-auto overscroll-contain pr-1">
              {listed.map((i) => (
                <ProblemRow
                  key={i}
                  index={i}
                  row={rowAt(i)}
                  problems={checks[i] ?? {}}
                  fields={fields}
                  fixed={!Object.keys(checks[i] ?? {}).length}
                  reduced={reduced}
                  onEdit={edit}
                />
              ))}
              {bad.length > SHOWN && (
                <p className="py-1 text-center text-[11.5px] text-muted-foreground">
                  and {count(bad.length - SHOWN)} more like these
                </p>
              )}
            </div>
            <div className="mt-2">
              <Switch
                on={skipBad}
                onToggle={() => setSkipBad((v) => !v)}
                label="Skip the rows that still need a look"
                reduced={reduced}
              />
            </div>
          </Fold>
          <Fold open={!bad.length && !fixing.length} reduced={reduced}>
            <div className="mt-4 flex items-center gap-3 rounded-[12px] px-3 py-3 shadow-[inset_0_0_0_1px_var(--border)]">
              <Drawn reduced={reduced} className="size-7" />
              <p className="text-[12.5px]">Every row looks right.</p>
            </div>
          </Fold>

          <div className="mt-4 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
            {blocked && (
              <p className="mr-auto text-[11.5px] text-amber-700 dark:text-amber-400">
                Fix the rows above, or skip them.
              </p>
            )}
            <button
              type="button"
              onClick={() => go("map")}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              Back
            </button>
            <StatusButton
              size="sm"
              labels={{
                idle: `Import ${count(ready)} ${ready === 1 ? noun.one : many}`,
              }}
              onClick={() => !blocked && ready > 0 && run()}
              aria-disabled={blocked || !ready || undefined}
              className={
                blocked || !ready ? "pointer-events-none opacity-50" : ""
              }
            />
          </div>
        </div>
      );
    }

    if (s === "import") {
      const share = progress.total ? progress.done / progress.total : 0;
      return (
        <div className="px-4 pb-5 @md:px-5">
          {header}
          <div
            className="mt-5 h-1 overflow-hidden rounded-full bg-muted"
            role="progressbar"
            aria-label={`Importing ${fileName}`}
            aria-valuemin={0}
            aria-valuemax={progress.total}
            aria-valuenow={progress.done}
          >
            <span
              className="block h-full origin-left rounded-full bg-primary"
              style={{
                transform: `scaleX(${share})`,
                transition: reduced ? "none" : `transform 360ms ${EASE}`,
              }}
            />
          </div>
          <div className="mt-3 flex items-center justify-between gap-3 text-[12.5px]">
            <p className="inline-flex items-baseline text-muted-foreground tabular-nums">
              <span className="font-medium text-foreground">
                <NumberRoll value={progress.done} />
              </span>
              &nbsp;of {count(progress.total)} {many}
            </p>
            <button
              type="button"
              onClick={() => ctrl.current?.abort()}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              Cancel
            </button>
          </div>
        </div>
      );
    }

    const r = result;
    return (
      <div className="flex flex-col items-center px-4 pt-2 pb-5 text-center @md:px-5">
        <Drawn
          reduced={reduced}
          tone={
            r?.imported
              ? "text-emerald-600 dark:text-emerald-400"
              : "text-amber-600 dark:text-amber-400"
          }
        />
        <p className="mt-3 text-[15px] font-medium tracking-[-0.01em] tabular-nums">
          {count(r?.imported ?? 0)} {r?.imported === 1 ? noun.one : many}{" "}
          imported
        </p>
        <p className="mt-1 text-[12px] text-muted-foreground">
          {r?.cancelled
            ? "You stopped it early; the rest weren't sent."
            : r?.skipped.length
              ? `${count(r.skipped.length)} skipped. Download them with the reason for each, fix them, and import that file.`
              : `Everything in ${fileName} is in.`}
        </p>
        <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
          {skippedHref && (
            <a
              href={skippedHref}
              download={`${fileName.replace(/\.[^.]+$/, "")}-skipped.csv`}
              className={`inline-flex h-8 items-center gap-1.5 rounded-full px-3 text-[12.5px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
            >
              <Download
                className="size-3.5"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              Skipped rows
            </a>
          )}
          <button
            type="button"
            onClick={reset}
            className={`inline-flex h-8 cursor-pointer items-center rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-colors hover:bg-primary/90 ${FOCUS}`}
          >
            Import another file
          </button>
        </div>
      </div>
    );
  };

  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="px-4 pt-4 pb-3.5 @md:px-5 @md:pt-5">
        <p className="text-[14px] font-medium tracking-[-0.01em]">{title}</p>
        <p className="mt-0.5 text-[12px] text-muted-foreground">
          {description}
        </p>
      </div>
      <Slides step={step} dir={dir} reduced={reduced} render={render} />
      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { PillSelect, type PillOption } from "./imported-pill-select";

/* ─────────────────────────────────────────────────────────
 * CSV MAPPER: your file's columns against your fields
 *
 *   threads   on a wide card each match is a thin line thread
 *             from the file's column to your field, drawn in
 *             when it's made
 *   drag      carry a column (or its dot) onto a field to match
 *             them; the thread follows the pointer. Or click a
 *             column, then a field
 *   select    every field also has a plain select, the whole
 *             mapping on a narrow card and for the keyboard
 * ───────────────────────────────────────────────────────── */

export interface MapperField {
  key: string;
  label: string;
  required?: boolean;
}

export interface CsvMapperProps {
  headers: string[];
  /** A few values from each column. */
  samples: string[][];
  fields: MapperField[];
  mapping: Record<string, number | null>;
  onChange: (mapping: Record<string, number | null>) => void;
  reduced: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const curve = (x1: number, y1: number, x2: number, y2: number) => {
  const dx = Math.max(24, (x2 - x1) / 2);
  return `M${x1} ${y1} C${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`;
};

function Thread({
  d,
  reduced,
  lit,
}: {
  d: string;
  reduced: boolean;
  lit: boolean;
}) {
  const ref = React.useRef<SVGPathElement>(null);
  React.useLayoutEffect(() => {
    if (!reduced)
      ref.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
        duration: 520,
        easing: EASE,
        fill: "backwards",
      });
  }, []);
  return (
    <path
      ref={ref}
      d={d}
      fill="none"
      stroke="var(--primary)"
      strokeWidth={lit ? 1.5 : 1}
      strokeOpacity={lit ? 0.9 : 0.5}
      pathLength={1}
      strokeDasharray={1}
      strokeDashoffset={0}
      style={{
        transition: reduced
          ? "none"
          : "stroke-opacity 200ms, stroke-width 200ms",
      }}
    />
  );
}

export function CsvMapper({
  headers,
  samples,
  fields,
  mapping,
  onChange,
  reduced,
}: CsvMapperProps) {
  const id = React.useId();
  const boxRef = React.useRef<HTMLDivElement>(null);
  const tempRef = React.useRef<SVGPathElement>(null);
  const [wide, setWide] = React.useState(false);
  const [lines, setLines] = React.useState<
    { key: string; col: number; d: string }[]
  >([]);
  const [picked, setPicked] = React.useState<number | null>(null);
  const [carrying, setCarrying] = React.useState<number | null>(null);
  const [hover, setHover] = React.useState<string | null>(null);
  const [size, setSize] = React.useState({ w: 0, h: 0 });

  const assign = (key: string, col: number | null) => {
    const next: Record<string, number | null> = { ...mapping };
    if (col !== null)
      for (const k of Object.keys(next)) if (next[k] === col) next[k] = null;
    next[key] = col;
    onChange(next);
  };
  const owner = (col: number) => fields.find((f) => mapping[f.key] === col);

  // Where each thread runs: from a column's dot to its field's dot.
  const measure = React.useCallback(() => {
    const box = boxRef.current;
    if (!box) return;
    const w = box.offsetWidth;
    const isWide = w >= 520;
    setWide((v) => (v === isWide ? v : isWide));
    setSize((s) =>
      s.w === w && s.h === box.offsetHeight ? s : { w, h: box.offsetHeight },
    );
    if (!isWide) return setLines((l) => (l.length ? [] : l));
    const r = box.getBoundingClientRect();
    const next: { key: string; col: number; d: string }[] = [];
    for (const f of fields) {
      const col = mapping[f.key];
      if (col === null || col === undefined) continue;
      const a = box
        .querySelector<HTMLElement>(`[data-col-dot="${col}"]`)
        ?.getBoundingClientRect();
      const b = box
        .querySelector<HTMLElement>(`[data-field-dot="${CSS.escape(f.key)}"]`)
        ?.getBoundingClientRect();
      if (!a || !b) continue;
      next.push({
        key: f.key,
        col,
        d: curve(
          a.left + a.width / 2 - r.left,
          a.top + a.height / 2 - r.top,
          b.left + b.width / 2 - r.left,
          b.top + b.height / 2 - r.top,
        ),
      });
    }
    setLines((l) =>
      l.length === next.length &&
      l.every((x, i) => x.d === next[i].d && x.key === next[i].key)
        ? l
        : next,
    );
  }, [fields, mapping]);

  React.useLayoutEffect(() => {
    measure();
    const box = boxRef.current;
    if (!box) return;
    const observer = new ResizeObserver(measure);
    observer.observe(box);
    return () => observer.disconnect();
  }, [measure]);

  // Carrying a column: a loose thread follows the pointer, written straight to the path.
  const carry = (col: number, e: React.PointerEvent) => {
    if (!wide || e.button !== 0) return;
    const box = boxRef.current;
    const dot = box?.querySelector<HTMLElement>(`[data-col-dot="${col}"]`);
    if (!box || !dot) return;
    const sx = e.clientX;
    const sy = e.clientY;
    let started = false;
    const move = (ev: PointerEvent) => {
      if (!started && Math.hypot(ev.clientX - sx, ev.clientY - sy) < 5) return;
      if (!started) {
        started = true;
        setCarrying(col);
      }
      const r = box.getBoundingClientRect();
      const a = dot.getBoundingClientRect();
      tempRef.current?.setAttribute(
        "d",
        curve(
          a.left + a.width / 2 - r.left,
          a.top + a.height / 2 - r.top,
          ev.clientX - r.left,
          ev.clientY - r.top,
        ),
      );
      const over = (
        document.elementFromPoint(ev.clientX, ev.clientY) as HTMLElement | null
      )?.closest<HTMLElement>("[data-field]");
      setHover((h) =>
        h === (over?.dataset.field ?? null) ? h : (over?.dataset.field ?? null),
      );
    };
    const up = (ev: PointerEvent) => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      if (!started) return;
      const over = (
        document.elementFromPoint(ev.clientX, ev.clientY) as HTMLElement | null
      )?.closest<HTMLElement>("[data-field]");
      if (over?.dataset.field) assign(over.dataset.field, col);
      setCarrying(null);
      setHover(null);
      tempRef.current?.setAttribute("d", "");
      // The click that ends a carry shouldn't also pick the column.
      window.addEventListener("click", (c) => c.stopPropagation(), {
        capture: true,
        once: true,
      });
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };

  React.useEffect(() => {
    if (picked === null) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setPicked(null);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [picked]);

  const lit = hover ?? (picked !== null ? (owner(picked)?.key ?? null) : null);
  const options = React.useMemo<PillOption[]>(
    () => [
      { value: "", label: "Don’t import" },
      ...headers.map((h, i) => ({
        value: String(i),
        label: h || `Column ${i + 1}`,
        description:
          samples[i]?.filter(Boolean).slice(0, 2).join(" · ") || "Empty",
      })),
    ],
    [headers, samples],
  );

  return (
    <div
      ref={boxRef}
      className={`relative ${wide ? "grid grid-cols-[minmax(0,1fr)_48px_minmax(0,1.1fr)]" : ""}`}
    >
      {wide && (
        <>
          <ol aria-label="Columns in your file" className="space-y-1.5">
            {headers.map((h, i) => {
              const used = owner(i);
              const on = picked === i || carrying === i;
              return (
                <li key={i}>
                  <button
                    type="button"
                    data-col={i}
                    aria-pressed={picked === i}
                    onPointerDown={(e) => carry(i, e)}
                    onClick={() => setPicked((p) => (p === i ? null : i))}
                    className={`relative flex w-full cursor-grab items-center gap-2 rounded-[10px] py-1.5 pr-5 pl-2.5 text-left transition-[background-color,box-shadow] active:cursor-grabbing ${FOCUS} ${
                      on
                        ? "bg-accent shadow-[inset_0_0_0_1px_var(--ring)]"
                        : "shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent/60"
                    }`}
                  >
                    <span className="min-w-0 flex-1">
                      <span
                        className={`block truncate font-mono text-[12px] ${used ? "text-foreground" : "text-muted-foreground"}`}
                      >
                        {h || `Column ${i + 1}`}
                      </span>
                      <span className="block truncate text-[11px] text-muted-foreground">
                        {samples[i]?.filter(Boolean).slice(0, 2).join(" · ") ||
                          "Empty"}
                      </span>
                    </span>
                    <span
                      data-col-dot={i}
                      aria-hidden="true"
                      className={`absolute top-1/2 -right-[5px] size-2.5 -translate-y-1/2 rounded-full transition-colors duration-300 ${used ? "bg-primary" : "bg-background shadow-[inset_0_0_0_1px_var(--muted-foreground)]"}`}
                    />
                  </button>
                </li>
              );
            })}
          </ol>
          <span aria-hidden="true" />
        </>
      )}

      <ol aria-label="Your fields" className="space-y-1.5">
        {fields.map((f) => {
          const col = mapping[f.key];
          const target = picked !== null || carrying !== null;
          const isLit = lit === f.key;
          return (
            <li
              key={f.key}
              data-field={f.key}
              onClick={(e) => {
                if (
                  picked === null ||
                  (e.target as HTMLElement).closest(
                    '[aria-haspopup="listbox"], [role="listbox"]',
                  )
                )
                  return;
                assign(f.key, picked);
                setPicked(null);
              }}
              className={`relative flex items-center gap-2 rounded-[10px] py-1.5 pr-1.5 pl-3 transition-[background-color,box-shadow] duration-200 ${
                isLit
                  ? "bg-accent shadow-[inset_0_0_0_1px_var(--ring)]"
                  : target
                    ? "cursor-pointer shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent/60"
                    : "shadow-[inset_0_0_0_1px_var(--border)]"
              }`}
            >
              {wide && (
                <span
                  data-field-dot={f.key}
                  aria-hidden="true"
                  className={`absolute top-1/2 -left-[5px] size-2.5 -translate-y-1/2 rounded-full transition-colors duration-300 ${col !== null && col !== undefined ? "bg-primary" : "bg-background shadow-[inset_0_0_0_1px_var(--muted-foreground)]"}`}
                />
              )}
              <span className="min-w-0 flex-1">
                <span
                  id={`${id}-${f.key}`}
                  className="block truncate text-[12.5px] font-medium"
                >
                  {f.label}
                  {f.required && (
                    <span className="text-muted-foreground"> *</span>
                  )}
                </span>
                {!wide && (
                  <span className="block truncate text-[11px] text-muted-foreground">
                    {col !== null && col !== undefined
                      ? samples[col]?.filter(Boolean).slice(0, 2).join(" · ") ||
                        "Empty"
                      : f.required
                        ? "Needed to import"
                        : "Not imported"}
                  </span>
                )}
              </span>
              <span className="flex w-[45%] max-w-[11rem] shrink-0">
                <PillSelect
                  block
                  mono
                  align="end"
                  width={250}
                  label={`Column for ${f.label}`}
                  options={options}
                  value={col === null || col === undefined ? "" : String(col)}
                  onValueChange={(v) =>
                    assign(f.key, v === "" ? null : Number(v))
                  }
                  muted={col === null || col === undefined}
                />
              </span>
            </li>
          );
        })}
      </ol>

      {wide && (
        <svg
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 overflow-visible"
          width={size.w}
          height={size.h}
        >
          {lines.map((l) => (
            <Thread
              key={`${l.key}:${l.col}`}
              d={l.d}
              reduced={reduced}
              lit={lit === l.key}
            />
          ))}
          <path
            ref={tempRef}
            d=""
            fill="none"
            stroke="var(--primary)"
            strokeWidth={1.5}
            strokeDasharray="3 3"
            style={{ opacity: carrying !== null ? 0.9 : 0 }}
          />
        </svg>
      )}
      <p className="sr-only" aria-live="polite">
        {picked !== null
          ? `${headers[picked] || `Column ${picked + 1}`} picked. Choose the field it fills.`
          : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PILL SELECT: a select that's the same surface as its pill
 *
 *   open      the pill grows into its list (size and corners
 *             ease) from the edge it's lined up with, while its
 *             label fades into the options; it opens upward when
 *             there's no room below, and long lists scroll
 *   pick      the list folds back into the pill and the label
 *             morphs to the new choice; the current option
 *             carries a drawn check
 *   keys      arrows move a highlight that glides between rows,
 *             Home and End jump, typing a few letters finds an
 *             option, Enter picks, Escape folds it back
 *
 * The list lives in a portal on the page's body, placed over
 * the pill, so a clipping toolbar, fold or scroller never cuts
 * it off; it carries the theme's colours with it. Scrolling
 * the page closes it.
 *
 * Used wherever a component needs a choice from a list; never
 * the browser's own dropdown, which can't follow the theme.
 * ───────────────────────────────────────────────────────── */

export interface PillOption {
  value: string;
  label: string;
  /** A second line in the list, e.g. a sample value. */
  description?: string;
}

export interface PillSelectProps {
  options: PillOption[];
  value: string | null | undefined;
  onValueChange: (value: string) => void;
  /** Accessible name, e.g. "Column for Email". */
  label: string;
  /** Shown while nothing is chosen. */
  placeholder?: string;
  /** What the pill shows for a choice; the option's label by default. */
  display?: (option: PillOption | undefined) => string;
  /** The pill's contents, when it needs more than text (an icon that turns). */
  renderValue?: (
    option: PillOption | undefined,
    open: boolean,
  ) => React.ReactNode;
  /** Monospace labels, for code-like values (event names, column headers). */
  mono?: boolean;
  /** Which edge of the pill the list lines up with. */
  align?: "start" | "end";
  /** The list's width; never narrower than the pill. */
  width?: number;
  /** Fill the width it's given. */
  block?: boolean;
  /** Dims the pill's text, e.g. for "Don't import". */
  muted?: boolean;
  disabled?: boolean;
  /** "sm" is the 28px pill for toolbars; "md" is 36px, the height of the other form fields. */
  size?: "sm" | "md";
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const MAX_LIST = 280;
const PILL_SIZE = {
  sm: "h-7 px-2.5 text-[12px]",
  md: "h-9 pl-4 pr-3.5 text-[13.5px]",
};
// The theme travels with the list, so it matches the pill wherever the pill's colours were set.
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3 shrink-0 text-muted-foreground"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function PillSelect({
  options,
  value,
  onValueChange,
  label,
  placeholder = "Choose",
  display,
  renderValue,
  mono = false,
  align = "start",
  width = 240,
  block = false,
  muted = false,
  disabled = false,
  size = "sm",
  className = "",
}: PillSelectProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({
    up: false,
    width,
    shift: 0,
    x: 0,
    y: 0,
    theme: {} as Record<string, string>,
  });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const typed = React.useRef({ text: "", at: 0 });
  const selected = options.find((o) => o.value === value);
  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }
  const text = display ? display(selected) : (selected?.label ?? placeholder);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const w = Math.min(Math.max(width, rect.width), vw - 24);
    // Lined up with the pill's edge, nudged back on screen.
    const shift =
      align === "start"
        ? Math.min(0, vw - 12 - (rect.left + w))
        : Math.max(0, 12 - (rect.right - w));
    const estimate =
      Math.min(
        MAX_LIST,
        options.length * (options.some((o) => o.description) ? 46 : 32),
      ) + 12;
    const vh = window.innerHeight;
    const below = vh - 8 - rect.top;
    const above = rect.bottom - 8;
    const up = below < estimate + 8 && above > below;
    // Fixed coordinates of the pill's corner the list grows from.
    const x = align === "start" ? rect.left : vw - rect.right;
    const y = up ? vh - rect.bottom : rect.top;
    const cs = getComputedStyle(wrap);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({ up, width: w, shift, x, y, theme });
  };

  const open = () => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        options.findIndex((o) => o.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (panel) setPanelHeight(panel.offsetHeight);
  }, [mounted, options]);

  // The highlight glides to the active row, and the list scrolls to keep it in view.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    const list = listRef.current;
    if (!row || !list) return;
    setHighlight((h) =>
      h.top === row.offsetTop &&
      h.height === row.offsetHeight &&
      h.ready === (h.ready || expanded)
        ? h
        : {
            top: row.offsetTop,
            height: row.offsetHeight,
            ready: h.ready || expanded,
          },
    );
    const scroller = list.parentElement;
    if (scroller && scroller.scrollHeight > scroller.clientHeight) {
      if (row.offsetTop < scroller.scrollTop)
        scroller.scrollTop = row.offsetTop - 4;
      else if (
        row.offsetTop + row.offsetHeight >
        scroller.scrollTop + scroller.clientHeight
      )
        scroller.scrollTop =
          row.offsetTop + row.offsetHeight - scroller.clientHeight + 4;
    }
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const inside = (n: Node) =>
      Boolean(wrapRef.current?.contains(n) || surfaceRef.current?.contains(n));
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) close(false);
    };
    // The list sits where the pill was; if the page moves under it, it goes at once rather than fold in the wrong place.
    const gone = () => {
      window.clearTimeout(timer.current);
      setPhase("closed");
    };
    const onScroll = (e: Event) => {
      if (!surfaceRef.current?.contains(e.target as Node)) gone();
    };
    const onResize = gone;
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, [expanded, close]);

  const choose = (o: PillOption) => {
    close();
    if (o.value !== value) onValueChange(o.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = options.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "PageDown") move(active + 6);
    else if (e.key === "PageUp") move(active - 6);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (options[active]) choose(options[active]);
    } else if (e.key === "Tab") close(false);
    else if (e.key.length === 1 && /\S/.test(e.key)) {
      // A few letters typed quickly find the option that starts with them.
      const now = performance.now();
      typed.current = {
        text:
          (now - typed.current.at < 700 ? typed.current.text : "") +
          e.key.toLowerCase(),
        at: now,
      };
      const hit = options.findIndex((o) =>
        o.label.toLowerCase().startsWith(typed.current.text),
      );
      if (hit !== -1) setActive(hit);
    }
  };

  const w = expanded ? fit.width : pill.width;
  const h = expanded ? panelHeight : pill.height;
  const listId = `${id}-list`;
  const pillText = renderValue ? null : (
    <>
      <span
        className={`min-w-0 flex-1 truncate text-left ${mono ? "font-mono text-[11.5px]" : ""} ${muted || !selected ? "text-muted-foreground" : "text-foreground"}`}
      >
        {block ? text : <TextMorph>{text}</TextMorph>}
      </span>
      <Chevron up={expanded} reduced={reduced} />
    </>
  );

  return (
    <div
      ref={wrapRef}
      className={`relative ${block ? "flex w-full min-w-0" : "inline-flex"} ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        const to = e.relatedTarget as Node | null;
        if (
          expanded &&
          document.hasFocus() &&
          !(
            to &&
            (wrapRef.current?.contains(to) || surfaceRef.current?.contains(to))
          )
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${selected?.label ?? placeholder}`}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            open();
          }
        }}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex ${PILL_SIZE[size]} min-w-0 cursor-pointer items-center gap-1.5 rounded-full font-medium whitespace-nowrap shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${block ? "w-full" : ""} ${quiet ? "outline-none" : FOCUS}`}
      >
        {renderValue ? renderValue(selected, expanded) : pillText}
      </button>

      {mounted &&
        createPortal(
          <div
            ref={surfaceRef}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                e.stopPropagation();
                close();
              }
            }}
            onPointerDown={(e) => {
              if (!(e.target as HTMLElement).closest("[data-scroll]"))
                e.preventDefault();
              setQuiet(true);
            }}
            className="fixed z-[60] overflow-hidden bg-popover text-popover-foreground"
            style={{
              ...fit.theme,
              [fit.up ? "bottom" : "top"]: fit.y,
              [align === "start" ? "left" : "right"]:
                fit.x +
                (expanded ? (align === "start" ? fit.shift : -fit.shift) : 0),
              width: w,
              height: h,
              borderRadius: expanded ? 16 : pill.height / 2,
              // The pill's own cavemio, the whole way: it is the same surface.
              boxShadow: "inset 0 0 0 1px var(--border)",
              transition: reduced
                ? "none"
                : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
            }}
          >
            {/* The pill's label, fading out as the surface grows and back in as it folds. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inline-flex ${PILL_SIZE[size]} items-center gap-1.5 font-medium whitespace-nowrap ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: pill.width,
                opacity: expanded ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
              }}
            >
              {renderValue ? renderValue(selected, expanded) : pillText}
            </span>
            <div
              ref={panelRef}
              className={`absolute p-1 ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: fit.width,
                opacity: expanded ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
              }}
            >
              <div
                data-scroll=""
                className="overflow-y-auto overscroll-contain"
                style={{ maxHeight: MAX_LIST }}
              >
                <div
                  ref={listRef}
                  id={listId}
                  role="listbox"
                  tabIndex={-1}
                  aria-label={label}
                  aria-activedescendant={`${id}-o${active}`}
                  onKeyDown={onListKey}
                  className="relative outline-none"
                >
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                    style={{
                      height: highlight.height,
                      transform: `translateY(${highlight.top}px)`,
                      opacity: highlight.ready ? 1 : 0,
                      transition:
                        highlight.ready && !reduced
                          ? `transform 260ms ${EASE}, height 260ms ${EASE}, opacity 200ms`
                          : "none",
                    }}
                  />
                  {options.map((o, i) => {
                    const on = o.value === value;
                    return (
                      <div
                        key={o.value}
                        ref={(el) => {
                          rowRefs.current[i] = el;
                        }}
                        id={`${id}-o${i}`}
                        role="option"
                        aria-selected={on}
                        onPointerMove={() => setActive(i)}
                        onClick={() => choose(o)}
                        className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-1.5"
                      >
                        <span className="min-w-0 flex-1">
                          <span
                            className={`block truncate ${mono ? "font-mono text-[12px]" : "text-[12.5px] font-medium"}`}
                          >
                            {o.label}
                          </span>
                          {o.description && (
                            <span className="mt-0.5 block truncate text-[11.5px] text-muted-foreground">
                              {o.description}
                            </span>
                          )}
                        </span>
                        <svg
                          viewBox="0 0 16 16"
                          fill="none"
                          aria-hidden="true"
                          className="mt-0.5 size-3.5 shrink-0"
                        >
                          <path
                            d="M3.5 8.5 6.5 11.5 12.5 4.5"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            pathLength={1}
                            strokeDasharray={1}
                            style={{
                              strokeDashoffset: on && expanded ? 0 : 1,
                              transition: reduced
                                ? "none"
                                : `stroke-dashoffset 380ms ${EASE} 160ms`,
                            }}
                          />
                        </svg>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

/* ─────────────────────────────────────────────────────────
 * CSV PARSE: reading, matching and writing CSV for csv-import
 *
 *   parse     RFC 4180: quoted fields, doubled quotes, commas
 *             and line breaks inside quotes, CRLF or LF, a
 *             byte-order mark. The separator (comma, semicolon,
 *             tab) is taken from the first line. Long files are
 *             read in slices with a pause between, so the page
 *             keeps drawing
 *   match     a column matches a field when their names agree
 *             once case, spaces and punctuation are ignored
 *             ("E-mail address" → email), or one contains the
 *             other
 *   write     the rows you skipped, back out as CSV
 * ───────────────────────────────────────────────────────── */

export interface CsvMatchable {
  key: string;
  label: string;
  /** Other names the column might have, e.g. ["e-mail", "email address"]. */
  match?: string[];
}

const SLICE = 200_000;
const pause = () => new Promise<void>((r) => setTimeout(r, 0));

/** The separator the first line uses most, outside quotes. */
export function detectDelimiter(text: string): string {
  const counts: Record<string, number> = { ",": 0, ";": 0, "\t": 0 };
  let quoted = false;
  for (let i = 0; i < text.length && i < 10_000; i++) {
    const c = text[i];
    if (c === '"') quoted = !quoted;
    else if (!quoted && (c === "\n" || c === "\r")) break;
    else if (!quoted && c in counts) counts[c]++;
  }
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0][1]
    ? Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0]
    : ",";
}

/** Every row as an array of fields; empty lines are dropped. */
export async function parseCsv(
  input: string,
  options: {
    delimiter?: string;
    onProgress?: (fraction: number) => void;
    signal?: AbortSignal;
  } = {},
): Promise<string[][]> {
  const text = input.charCodeAt(0) === 0xfeff ? input.slice(1) : input;
  const d = options.delimiter ?? detectDelimiter(text);
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  let start = 0;
  const n = text.length;
  for (let i = 0; i < n; i++) {
    const c = text.charCodeAt(i);
    if (quoted) {
      if (c === 34) {
        if (text.charCodeAt(i + 1) === 34) {
          field += text.slice(start, i + 1);
          i++;
          start = i + 1;
        } else {
          field += text.slice(start, i);
          quoted = false;
          start = i + 1;
        }
      }
    } else if (c === 34 && field === "" && start === i) {
      quoted = true;
      start = i + 1;
    } else if (text[i] === d) {
      row.push(field + text.slice(start, i));
      field = "";
      start = i + 1;
    } else if (c === 10 || c === 13) {
      row.push(field + text.slice(start, i));
      if (row.length > 1 || row[0] !== "") rows.push(row);
      row = [];
      field = "";
      if (c === 13 && text.charCodeAt(i + 1) === 10) i++;
      start = i + 1;
    }
    if (i % SLICE === 0 && i) {
      if (options.signal?.aborted)
        throw new DOMException("Aborted", "AbortError");
      options.onProgress?.(i / n);
      await pause();
    }
  }
  if (start < n || field || row.length) {
    row.push(field + text.slice(start, quoted ? n : n));
    if (row.length > 1 || row[0] !== "") rows.push(row);
  }
  options.onProgress?.(1);
  return rows;
}

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

/** Which column (by index) each field should take, or null. Each column is used once. */
export function autoMatch(
  headers: string[],
  fields: CsvMatchable[],
): Record<string, number | null> {
  const used = new Set<number>();
  const out: Record<string, number | null> = {};
  const heads = headers.map(norm);
  for (const f of fields) {
    const names = [f.key, f.label, ...(f.match ?? [])]
      .map(norm)
      .filter(Boolean);
    let hit = heads.findIndex((h, i) => !used.has(i) && names.includes(h));
    if (hit === -1)
      hit = heads.findIndex(
        (h, i) =>
          !used.has(i) &&
          h.length > 2 &&
          names.some((x) => x.length > 2 && (h.includes(x) || x.includes(h))),
      );
    out[f.key] = hit === -1 ? null : hit;
    if (hit !== -1) used.add(hit);
  }
  return out;
}

/** Rows back out as CSV text, quoting what needs it. */
export function toCsv(rows: string[][]): string {
  const esc = (v: string) =>
    /[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
  return rows.map((r) => r.map(esc).join(",")).join("\r\n");
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

